 Sleeve_Type, Neck_Collar_Type, sub_category, CategoryType, Garment_Length_Type as garment_length, upper(coalesce(sm.size,COALESCE(REGEXP_EXTRACT(s.Sub_Category_Name, r\'_(.*?)-\'), REGEXP_EXTRACT(sm.SKU, r\'_(.*)$\')))) as size, ssoc.Store_Rent, ssoc.Store_Staff_Salary, ssoc.Water_and_Electricity_Bill, ssoc.Pantry_office_Exp, ssoc.Staff_welfare_Exp, ssoc.System_Charge_Exp, ssoc.Travel_Exp, ssoc.Cab_Travel_Exp, ssoc.Alteration_Exp, ssoc.Store_Maintenance_Exp FROM saadaa-wh.`MAPLEMONK.saadaa_s3_saadaa_store_sales` s LEFT JOIN saadaa-wh.maplemonk.easyecom_saadaa_product_master sm ON lower(s.Sub_Category_Name) = lower(sm.sku) LEFT JOIN (select * from (select replace(commonsku,\' \',\'\') skucode ,commonsku , product_name name , cast(category as string) category ,cast(sub_category as string) as sub_category ,cast(Gender as string) as Gender ,categoryType ,Garment_Length_Type ,Color_Family ,Product_Type ,Product_Variant ,FitType ,Sleeve_Type ,Neck_Collar_Type ,Size ,row_number() over (partition by replace(commonsku,\' \',\'\') order by length(commonsku) desc) rw from maplemonk.saadaa_final_sku_master ) where rw = 1 ) p on lower(replace(s.Sub_Category_Name,\' \',\'\')) = lower(p.skucode) LEFT JOIN (select PARSE_DATE(\'%B %Y\', Particulars) Month, cast(Rent as float64) Store_Rent, cast(Salary as float64) Store_Staff_Salary, safe_cast(Water_and_Electricity as float64) Water_and_Electricity_Bill, safe_cast(Pantry_office__BizPay_Exp_ as float64) Pantry_office_Exp, safe_cast(Staff_welfare__BizPay_Exp_ as float64) Staff_welfare_Exp, safe_cast(System_Charge__BizPay_Exp_ as float64) System_Charge_Exp, safe_cast(Travel_CAR_BIKE__BizPay_Exp_ as float64) Travel_Exp, safe_cast(Travel_OLA_UBER__BizPay_Exp_ as float64) Cab_Travel_Exp, safe_cast(Alteration_Charges__BizPay_Exp_ as float64) Alteration_Exp, safe_cast(Store_Maintenance___Upkeep__BizPay_ as float64) Store_Maintenance_Exp from maplemonk.Google_Sheets_Store_operational_Cost) ssoc on ssoc.month = date_trunc(cast(FORMAT_DATE(\'%